"""Era I battle sprites for all Spirlings (original designs, generated by this script).

Each Spirling is a list of parts (ellipses / polygons) drawn back to front. Every part gets a
dark outline ring, a mid base, a highlight on its top-left edge and a dithered shadow on its
bottom-right edge, all in the four Era I shades. Small details (eyes, marks) are stamped.

Front sprites face left (toward the player's side). Back sprites mirror the body, drop the
face, and sit a little lower so the bottom edge is cropped.
Writes art/era1/spirlings/<name>_front.png and <name>_back.png (56 x 56).
Run: python3 tools/art/gen_spirlings.py (from the repo root).
"""
from __future__ import annotations

import os

from px import Canvas, ellipse_mask, poly_mask, union

S = 56
TONES = {  # base, shadow, highlight
    "light": (3, 2, 3),
    "mid": (2, 1, 3),
    "dark": (1, 0, 2),
    "ink": (0, 0, 1),
}


class Part:
    def __init__(self, mask, tone="mid", outline=True, face=False, shade=True):
        self.mask, self.tone, self.outline, self.face, self.shade = mask, tone, outline, face, shade


def E(cx, cy, rx, ry, tone="mid", **kw):
    return Part(ellipse_mask(cx, cy, rx, ry), tone, **kw)


def P(points, tone="mid", **kw):
    return Part(poly_mask(points), tone, **kw)


class Stamp:
    def __init__(self, x, y, rows, face=True):
        self.x, self.y, self.rows, self.face = x, y, rows, face


def eye(x, y, big=False):
    if big:
        return Stamp(x, y, [".00.", "0330", "0300", "0000", ".00."])
    return Stamp(x, y, ["00", "30", "00"])


def glow_eye(x, y):
    return Stamp(x, y, ["000", "033", "000"])


def render(parts, back=False) -> Canvas:
    c = Canvas(S, S)
    for part in parts:
        if back and part.face:
            continue
        if isinstance(part, Stamp):
            c.ascii(part.x, part.y, part.rows)
            continue
        inside = [[part.mask(x, y) for x in range(S)] for y in range(S)]

        def ins(x, y):
            return 0 <= x < S and 0 <= y < S and inside[y][x]

        base, shadow, hi = TONES[part.tone]
        if part.outline:
            for y in range(S):
                for x in range(S):
                    if not inside[y][x] and (ins(x - 1, y) or ins(x + 1, y) or ins(x, y - 1) or ins(x, y + 1)):
                        c.set(x, y, 0)
        for y in range(S):
            for x in range(S):
                if not inside[y][x]:
                    continue
                v = base
                if part.shade:
                    if not ins(x + 1, y + 1) or not ins(x + 1, y):
                        v = shadow
                    elif not ins(x + 2, y + 2) and (x + y) % 2 == 0:
                        v = shadow
                    elif not ins(x - 1, y - 1) or not ins(x, y - 1):
                        v = hi
                c.set(x, y, v)
    return c


def shift_down(c: Canvas, dy: int) -> Canvas:
    out = Canvas(S, S)
    for y in range(S - dy):
        out.px[y + dy] = list(c.px[y])
    return out


