    # Grown Puddlet: longer droplet body, a dorsal fin ridge and a split tail fin.
    return grown(puddlet, 1.15, 1.15, ax=34, before=[
        P([(26, 22), (34, 10), (36, 22), (42, 16), (40, 30)], "mid"),
        P([(44, 44), (56, 50), (50, 54)], "mid")])


